def require(condition: bool, message: str) -> None:
    if not bool(condition):
        raise RuntimeError(message)

def canonical_json_bytes(obj: Any) -> bytes:
    return json.dumps(
        obj,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")

def sha256_file(path: Path, chunk_bytes: int = 8 * 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while True:
            chunk = handle.read(chunk_bytes)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()

def normalize_bool(series: pd.Series, name: str) -> pd.Series:
    if pd.api.types.is_bool_dtype(series.dtype):
        return series.fillna(False).astype(bool)
    mapping = {
        True: True, False: False, 1: True, 0: False,
        "1": True, "0": False, "true": True, "false": False,
        "True": True, "False": False, "yes": True, "no": False,
    }
    converted = series.map(mapping)
    bad = series.notna() & converted.isna()
    if bad.any():
        examples = series.loc[bad].astype(str).unique()[:8].tolist()
        raise RuntimeError(f"Cannot normalize boolean column {name}; examples={examples}")
    return converted.fillna(False).astype(bool)

def wilson_interval(successes: int, total: int, z: float = 1.959963984540054) -> tuple[float, float]:
    if total <= 0:
        return np.nan, np.nan
    proportion = successes / total
    denominator = 1.0 + z * z / total
    centre = (proportion + z * z / (2.0 * total)) / denominator
    radius = z * math.sqrt(proportion * (1.0 - proportion) / total + z * z / (4.0 * total * total)) / denominator
    return float(max(0.0, centre - radius)), float(min(1.0, centre + radius))

def evenly_spaced_indices(length: int, maximum: int) -> np.ndarray:
    require(length > 0 and maximum > 0, "Reservoir length and maximum must be positive")
    if length <= maximum:
        return np.arange(length, dtype=np.int64)
    return np.unique(np.rint(np.linspace(0, length - 1, maximum)).astype(np.int64))

def transform_target_array(values: np.ndarray, target: str) -> np.ndarray:
    values = np.asarray(values, dtype=np.float64)
    if TARGET_SPECS[target]["transform"] == "log1p":
        require((values >= 0.0).all(), f"{target}: log1p received negative observed targets")
        return np.log1p(values)
    return values

def inverse_scaled_target(values: np.ndarray, target: str, target_scaler: dict[str, Any]) -> np.ndarray:
    state = target_scaler["targets"][target]
    restored = np.asarray(values, dtype=np.float64) * float(state["std"]) + float(state["mean"])
    if state["transform"] == "log1p":
        restored = np.expm1(restored)
    if target == "soh30":
        return np.clip(restored, 0.0, 1.5)
    return np.maximum(restored, 0.0)

def active_target_row_mask(rows: pd.DataFrame, target_scaler: dict[str, Any]) -> pd.Series:
    active_any = pd.Series(False, index=rows.index, dtype=bool)
    for target in TCN_TARGET_ORDER:
        if bool(target_scaler["targets"][target].get("active", True)):
            spec = TARGET_SPECS[target]
            active_any |= normalize_bool(rows[spec["mask_col"]], spec["mask_col"])
    return active_any

class MultitaskCycleWindowIterator:
    def __init__(self, rows: pd.DataFrame, cycle_scaler: dict[str, Any], target_scaler: dict[str, Any]):
        active_any = active_target_row_mask(rows, target_scaler)
        self.rows = (
            rows.loc[active_any]
            .sort_values(["canonical_cell_id", "t_cycle"], kind="mergesort")
            .reset_index(drop=True)
        )
        self.cycle_scaler = cycle_scaler
        self.target_scaler = target_scaler
        self.groups = {
            str(cell): group.reset_index(drop=True)
            for cell, group in self.rows.groupby("canonical_cell_id", sort=True)
        }
        require(self.groups, "Multitask iterator has no cell groups")

    def _materialize(self, cycle_frame: pd.DataFrame, rows: pd.DataFrame) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        x = make_window_inputs(cycle_frame, rows, self.cycle_scaler)
        y, masks = encode_multitask_targets(rows, self.target_scaler)
        return x, y, masks

    def iter_cell_balanced_microbatches(
        self, *, epoch: int
    ) -> Iterator[tuple[np.ndarray, np.ndarray, np.ndarray, pd.DataFrame]]:
        rng = np.random.default_rng(SEED + 1009 * int(epoch))
        cells = np.asarray(sorted(self.groups), dtype=object)
        rng.shuffle(cells)
        padding = (-len(cells)) % TCN_GRAD_ACCUM_STEPS
        if padding:
            cells = np.concatenate([cells, cells[:padding]])
        for cell_id_value in cells:
            cell_id = str(cell_id_value)
            rows = self.groups[cell_id]
            replace = len(rows) < TCN_MICRO_BATCH_SIZE
            selected = rng.choice(len(rows), size=TCN_MICRO_BATCH_SIZE, replace=replace)
            batch_rows = rows.iloc[selected].reset_index(drop=True)
            cycle_frame = load_cycle_shard(cell_id)
            x, y, masks = self._materialize(cycle_frame, batch_rows)
            yield x, y, masks, batch_rows
            del cycle_frame

    def iter_prediction_batches(
        self,
    ) -> Iterator[tuple[np.ndarray, np.ndarray, np.ndarray, pd.DataFrame]]:
        for ordinal, (cell_id, rows) in enumerate(self.groups.items(), start=1):
            cycle_frame = load_cycle_shard(cell_id)
            for start in range(0, len(rows), TCN_PREDICTION_BATCH_SIZE):
                batch_rows = rows.iloc[start:start + TCN_PREDICTION_BATCH_SIZE].reset_index(drop=True)
                x, y, masks = self._materialize(cycle_frame, batch_rows)
                yield x, y, masks, batch_rows
            del cycle_frame
            if ordinal % 50 == 0:
                gc.collect()

class CausalConv1d(nn.Conv1d):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, dilation: int):
        self.left_padding = (kernel_size - 1) * dilation
        super().__init__(
            in_channels,
            out_channels,
            kernel_size,
            padding=self.left_padding,
            dilation=dilation,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        output = super().forward(x)
        return output[:, :, :-self.left_padding] if self.left_padding else output

class ResidualTCNBlock(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, dilation: int, dropout: float):
        super().__init__()
        self.conv1 = CausalConv1d(in_channels, out_channels, kernel_size, dilation)
        self.conv2 = CausalConv1d(out_channels, out_channels, kernel_size, dilation)
        self.dropout = nn.Dropout(dropout)
        self.projection = nn.Conv1d(in_channels, out_channels, 1) if in_channels != out_channels else nn.Identity()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        residual = self.projection(x)
        hidden = self.dropout(F.relu(self.conv1(x)))
        hidden = self.dropout(F.relu(self.conv2(hidden)))
        return F.relu(hidden + residual)

class OrderedQuantileHead(nn.Module):
    def __init__(self, in_features: int):
        super().__init__()
        self.projection = nn.Linear(in_features, 3)

    def forward(self, hidden: torch.Tensor) -> torch.Tensor:
        raw = self.projection(hidden)
        q50 = raw[:, 0]
        lower_gap = F.softplus(raw[:, 1])
        upper_gap = F.softplus(raw[:, 2])
        return torch.stack([q50 - lower_gap, q50, q50 + upper_gap], dim=1)

class MultitaskQuantileTCN(nn.Module):
    def __init__(self):
        super().__init__()
        blocks: list[nn.Module] = []
        in_channels = 96
        for out_channels, dilation in zip(TCN_BLOCK_CHANNELS, TCN_DILATIONS):
            blocks.append(
                ResidualTCNBlock(
                    in_channels,
                    out_channels,
                    TCN_KERNEL_SIZE,
                    dilation=dilation,
                    dropout=TCN_DROPOUT,
                )
            )
            in_channels = out_channels
        self.shared_trunk = nn.Sequential(*blocks)
        self.task_heads = nn.ModuleDict({
            target: OrderedQuantileHead(TCN_BLOCK_CHANNELS[-1]) for target in TCN_TARGET_ORDER
        })

    def forward(self, logical_window: torch.Tensor) -> dict[str, torch.Tensor]:
        if logical_window.ndim != 3 or logical_window.shape[1:] != (30, 96):
            raise RuntimeError(f"Expected [batch,30,96], received {tuple(logical_window.shape)}")
        channels_first = logical_window.transpose(1, 2)
        if channels_first.shape[1:] != (96, 30):
            raise RuntimeError(f"Conv1d input must be [batch,96,30], received {tuple(channels_first.shape)}")
        hidden = self.shared_trunk(channels_first)[:, :, -1]
        return {target: self.task_heads[target](hidden) for target in TCN_TARGET_ORDER}

def autocast_context(device: "torch.device"):
    if device.type == "cuda":
        return torch.autocast(device_type="cuda", dtype=torch.float16)
    return nullcontext()

def make_grad_scaler(enabled: bool):
    try:
        return torch.amp.GradScaler("cuda", enabled=enabled)
    except (AttributeError, TypeError):
        return torch.cuda.amp.GradScaler(enabled=enabled)

def safe_torch_load(path: Path, device: "torch.device") -> dict[str, Any]:
    try:
        return torch.load(path, map_location=device, weights_only=True)
    except TypeError:
        return torch.load(path, map_location=device)

def deterministic_fold_seed(mode: str, entity: str, inner_fold: int) -> int:
    token = f"{SEED}|{mode}|{entity}|{inner_fold}|multitask"
    return SEED + int(hashlib.sha256(token.encode("utf-8")).hexdigest()[:8], 16) % 1_000_000

def evaluate_tcn_rul90_macro_cell_rmsle(
    model: "nn.Module",
    iterator: MultitaskCycleWindowIterator,
    target_scaler: dict[str, Any],
    device: "torch.device",
) -> tuple[float, dict[str, Any]]:
    """Select epochs using only inner-validation RUL90 q50; source-balanced after cell means."""
    model.eval()
    cell_squared_errors: dict[str, list[float]] = {}
    cell_sources: dict[str, str] = {}
    with torch.no_grad():
        for x_np, _, mask_np, rows in iterator.iter_prediction_batches():
            x = torch.from_numpy(x_np).to(device)
            with autocast_context(device):
                prediction = model(x)["rul90"].detach().float().cpu().numpy()
            observed = mask_np[:, TCN_TARGET_ORDER.index("rul90")].astype(bool)
            if not observed.any():
                continue
            predicted_cycles = inverse_scaled_target(prediction[observed, 1], "rul90", target_scaler)
            true_cycles = rows.loc[observed, "rul90_cycles"].to_numpy(dtype=np.float64)
            require(np.isfinite(predicted_cycles).all(), "RUL90 epoch-selection predictions contain NaN/inf")
            require(np.isfinite(true_cycles).all() and (true_cycles >= 0.0).all(), "RUL90 validation labels are invalid")
            selected_rows = rows.loc[observed].reset_index(drop=True)
            squared = (np.log1p(predicted_cycles) - np.log1p(true_cycles)) ** 2
            for cell_id, group in selected_rows.groupby("canonical_cell_id", sort=True):
                key = str(cell_id)
                cell_squared_errors.setdefault(key, []).extend(squared[group.index].tolist())
                source_values = group["source"].astype(str).unique().tolist()
                require(len(source_values) == 1, f"Cell {key} maps to multiple sources")
                cell_sources[key] = source_values[0]
    require(cell_squared_errors, "NO_RUL90_VALIDATION_SUPPORT")
    cell_scores = {cell: float(np.sqrt(np.mean(values))) for cell, values in cell_squared_errors.items()}
    source_scores: dict[str, list[float]] = {}
    for cell, score in cell_scores.items():
        source_scores.setdefault(cell_sources[cell], []).append(score)
    source_means = {source: float(np.mean(scores)) for source, scores in source_scores.items()}
    score = float(np.mean(list(source_means.values())))
    return score, {
        "rul90_cells": int(len(cell_scores)),
        "rul90_sources": int(len(source_means)),
        "rul90_source_scores": source_means,
    }

def checkpoint_integrity_is_valid(checkpoint_path: Path) -> bool:
    sidecar = checkpoint_integrity_path(checkpoint_path)
    if not checkpoint_path.is_file() or not sidecar.is_file():
        return False
    try:
        payload = json.loads(sidecar.read_text(encoding="utf-8"))
    except Exception:
        return False
    return (
        payload.get("pipeline_config_hash") == PIPELINE_CONFIG_HASH
        and payload.get("input_hashes_sha256") == sha256_json(INPUT_HASHES)
        and int(payload.get("size_bytes", -1)) == int(checkpoint_path.stat().st_size)
        and payload.get("sha256") == sha256_file(checkpoint_path)
    )
